package com.nimbusbill.customer.controller; import com.nimbusbill.customer.dto.*; import com.nimbusbill.customer.service.CustomerConfigurationService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/customers/{customerId}") public class CustomerConfigurationController{private final CustomerConfigurationService service;public CustomerConfigurationController(CustomerConfigurationService s){service=s;}@GetMapping("/products") @PreAuthorize("hasAnyRole('ADMIN','BILLING_MANAGER','OPERATIONS','AUDITOR','READ_ONLY')") List<CustomerProductResponse> products(@PathVariable UUID customerId){return service.products(customerId);}@PutMapping("/products") @PreAuthorize("hasAnyRole('ADMIN','OPERATIONS')") List<CustomerProductResponse> setProducts(@PathVariable UUID customerId,@Valid @RequestBody List<CustomerProductRequest> r){return service.setProducts(customerId,r);}@GetMapping("/pricing") @PreAuthorize("hasAnyRole('ADMIN','BILLING_MANAGER','FINANCE','AUDITOR','READ_ONLY')") List<CustomerPricingResponse> pricing(@PathVariable UUID customerId){return service.pricing(customerId);}@PostMapping("/pricing") @PreAuthorize("hasAnyRole('ADMIN','BILLING_MANAGER')") CustomerPricingResponse assign(@PathVariable UUID customerId,@Valid @RequestBody CustomerPricingRequest r){return service.assign(customerId,r);}}
